import { z } from "zod";

const RunScope = z.object({
  agent: z.enum(["nova", "cifix", "upgrade", "flaky", "bugfix"]),
  repo: z.string().regex(/^RhinoHealth\/[\w.-]+$/),
  branch: z.string().startsWith("nova/"),
  jiraKey: z.string().regex(/^RH-\d+$/),
});
type RunScope = z.infer<typeof RunScope>;

const good: RunScope = RunScope.parse({ agent: "nova", repo: "RhinoHealth/fcp", branch: "nova/RH-1234", jiraKey: "RH-1234" });
console.log("ok:", good.repo, good.branch);

const bad = RunScope.safeParse({ agent: "root", repo: "evil/fcp", branch: "main", jiraKey: "RH-1234" });
if (!bad.success) console.log(z.prettifyError(bad.error));
